pid_t target_pid = 1000;
int pidfd;

// Creates a file descriptor (close-on-exec)
// referring to the process with target_pid
pidfd = pidfd_open(target_pid, 0);

if (pidfd < 0) {
    // Common Errors: ESRCH, EINVAL, EMFILE
    return -1;
}

// Usage with PIDFD_NONBLOCK flag
int nonblock_fd = pidfd_open(target_pid, PIDFD_NONBLOCK);

// Must be closed when done
close(pidfd);
